# blocking - synchronous
set {_request} to prepare GET request on "https://dummyjson.com/products/1"
set {_request}'s headers to "{'Content-Type':'application/json'}"
execute {_request}

set {_response} to last response of {_request}

if {_response}'s status is "OK":
    send "Request was successful!"
    send {_response}'s body
    send {_response}'s headers
    send {_response}'s status code
else:
    send "Request failed!"

set {_data} to json from "{a: 1, nested: {x: 1}}"
remove path "nested.x" from {_data}
delete path "a" in {_data}

# Broadcast online moderators
loop all players:
	if loop-value does not have permission "moderator":
		continue # filter out non moderators
	broadcast "%loop-player% is a moderator!" # Only moderators get broadcast
# Game starting counter
set {_counter} to 11
while {_counter} > 0:
	remove 1 from {_counter}
	wait a second
	if {_counter} != 1, 2, 3, 5 or 10:
		continue # only print when counter is 1, 2, 3, 5 or 10
	broadcast "Game starting in %{_counter}% second(s)"

function double(i: number) :: number:
	return 2 * {_i}
function divide(i: number) returns number:
	return {_i} / 2
